# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">LİPİTLERİN SINIFLANDIRILMASI VE TRİGLİSERİT SENTEZİ (BİY.9.1.6)</text>\n  <rect x="20" y="45" width="210" height="95" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. NÖTRAL YAĞLAR (TRİGLİSERİT)</text>\n  <text x="125" y="86" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Depo ve Enerji Lipitleri</text>\n  <text x="125" y="106" text-anchor="middle" font-size="10.5" fill="#1d4ed8">1 Gliserol + 3 Yağ Asidi</text>\n  <text x="125" y="124" text-anchor="middle" font-size="10.5" fill="#1d4ed8">3 Ester Bağı + 3 H₂O (Dehidrasyon)</text>\n  <rect x="245" y="45" width="210" height="95" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. FOSFOLİPİTLER</text>\n  <text x="350" y="86" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Hücre Zarının Çift Katlı Yapısı</text>\n  <text x="350" y="106" text-anchor="middle" font-size="10.5" fill="#166534">Hidrofilik Baş (Gliserol + Fosfat + Kolin)</text>\n  <text x="350" y="124" text-anchor="middle" font-size="10.5" fill="#166534">Hidrofobik Kuyruk (2 Yağ Asidi)</text>\n  <rect x="470" y="45" width="210" height="95" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">3. STEROİTLER</text>\n  <text x="575" y="86" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Düzenleyici Halkasal Lipitler</text>\n  <text x="575" y="106" text-anchor="middle" font-size="10.5" fill="#78350f">Ester bağı içermez, monomerdir.</text>\n  <text x="575" y="124" text-anchor="middle" font-size="10.5" fill="#78350f">Kolesterol, D vitamini, Eşey hormonları</text>\n  <rect x="20" y="152" width="660" height="92" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">DOYMUŞ VE DOYMAMIŞ YAĞ ASİTLERİ KARŞILAŞTIRMASI</text>\n  <text x="38" y="198" font-size="11" font-weight="bold" fill="#581c87">• Doymuş Yağ Asidi: Karbonlar arası tekli bağ (C–C) vardır; oda sıcaklığında katıdır (tereyağı, kuyruk yağı).</text>\n  <text x="38" y="222" font-size="11" font-weight="bold" fill="#581c87">• Doymamış Yağ Asidi: En az bir çift bağ (C=C) içerir; oda sıcaklığında sıvıdır (zeytinyağı, ayçiçek yağı).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AMİNO ASİT YAPISI VE PEPTİT BAĞI OLUŞUMU (PROTEİNLER)</text>\n  <rect x="20" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="175" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">BİR AMİNO ASİDİN GENEL YAPISI</text>\n  <circle cx="175" cy="135" r="22" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="175" y="140" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">C</text>\n  <rect x="40" y="117" width="85" height="36" rx="6" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="82" y="133" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">–NH₂</text>\n  <text x="82" y="147" text-anchor="middle" font-size="9.5" fill="#166534">Amino (Bazik)</text>\n  <line x1="125" y1="135" x2="153" y2="135" stroke="#334155" stroke-width="2"/>\n  <rect x="225" y="117" width="85" height="36" rx="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="267" y="133" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">–COOH</text>\n  <text x="267" y="147" text-anchor="middle" font-size="9.5" fill="#991b1b">Karboksil (Asit)</text>\n  <line x1="197" y1="135" x2="225" y2="135" stroke="#334155" stroke-width="2"/>\n  <text x="175" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#334155">H (Hidrojen)</text>\n  <line x1="175" y1="102" x2="175" y2="113" stroke="#334155" stroke-width="2"/>\n  <rect x="115" y="182" width="120" height="40" rx="6" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="175" y="199" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">–R (Radikal Grup)</text>\n  <text x="175" y="214" text-anchor="middle" font-size="9.5" fill="#78350f">20 çeşidi belirler</text>\n  <line x1="175" y1="157" x2="175" y2="182" stroke="#334155" stroke-width="2"/>\n  <rect x="350" y="45" width="330" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">PEPTİTLEŞME (DEHİDRASYON SENTEZİ)</text>\n  <text x="368" y="96" font-size="11" font-weight="bold" fill="#14532d">• Amino Asit₁ + Amino Asit₂ → Dipeptit + H₂O</text>\n  <text x="368" y="120" font-size="10.5" fill="#166534">• Birinci amino asidin karboksil (–COOH) grubu ile</text>\n  <text x="368" y="138" font-size="10.5" fill="#166534">  ikinci amino asidin amino (–NH₂) grubu arasında</text>\n  <text x="368" y="156" font-size="10.5" font-weight="bold" fill="#15803d">  PEPTİT BAĞI kurulur ve 1 molekül su açığa çıkar.</text>\n  <rect x="368" y="172" width="294" height="54" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="515" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">n Amino Asit → Polipeptit + (n - 1) H₂O</text>\n  <text x="515" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Kurulan Peptit Bağı Sayısı = Açığa Çıkan Su = n - 1</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PROTEİNLERİN GÖREVLERİ VE DENATÜRASYON - RENATÜRASYON</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">PROTEİNLERİN BİYOLOJİK İŞLEVLERİ</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#78350f">• Katalizör: Enzimlerin yapısına katılır.</text>\n  <text x="35" y="116" font-size="10.5" font-weight="bold" fill="#78350f">• Savunma: Antikor ve interferon üretimi sağlar.</text>\n  <text x="35" y="138" font-size="10.5" font-weight="bold" fill="#78350f">• Taşıma: Hemoglobin O₂ ve CO₂ gazlarını taşır.</text>\n  <text x="35" y="160" font-size="10.5" font-weight="bold" fill="#78350f">• Hareket: Kaslardaki aktin ve miyozin iplikleri.</text>\n  <text x="35" y="182" font-size="10.5" font-weight="bold" fill="#78350f">• Yapısal: Keratin (saç, tırnak) ve kollajen (bağ doku).</text>\n  <text x="35" y="204" font-size="10.5" font-weight="bold" fill="#78350f">• Düzenleyici: İnsülin ve büyüme hormonu yapısı.</text>\n  <text x="35" y="226" font-size="10.5" font-weight="bold" fill="#b91c1c">• DNA şifresine göre ribozomda sentezlenir!</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">DENATÜRASYON (ÜÇ BOYUTLU YAPI KAYBI)</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Etkenler: Yüksek sıcaklık, aşırı pH, yoğun tuz, basınç.</text>\n  <text x="375" y="120" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Bozulma: Üç boyutlu özgül katlanma açılır ve</text>\n  <text x="375" y="138" font-size="10.5" font-weight="bold" fill="#7f1d1d">  protein biyolojik işlevini kaybeder.</text>\n  <rect x="375" y="154" width="290" height="72" rx="8" fill="#ffffff" stroke="#fca5a5" stroke-width="1.5"/>\n  <text x="520" y="175" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">ÇOK ÖNEMLİ KURAL:</text>\n  <text x="520" y="195" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0f172a">Denatürasyonda birincil yapıdaki PEPTİT BAĞLARI</text>\n  <text x="520" y="213" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0f172a">KOPMAZ; amino asit sayısı ve dizilimi değişmez!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
